#!/usr/bin/env -S deno run --check --allow-write=. --allow-read=. --lock=./tools/deno.lock.json
// Copyright 2018-2026 the Deno authors. MIT license.
import { createWorkflow, step } from "../../tools/gagen/mod.ts";
import { installEndeStep } from "./common.ts";

const workflow = createWorkflow({
  name: "start_release",
  // The version is the UTC date of the release (ChronVer), so there is
  // nothing to choose.
  on: {
    workflow_dispatch: {},
  },
  jobs: [{
    id: "build",
    name: "start release",
    runsOn: "ubuntu-24.04",
    timeoutMinutes: 30,
    env: {
      CARGO_TERM_COLOR: "always",
      RUST_BACKTRACE: "full",
      RUSTC_FORCE_INCREMENTAL: 1,
    },
    steps: [
      step({
        name: "Configure git",
        run: [
          "git config --global core.symlinks true",
          "git config --global fetch.parallel 32",
        ],
      }),
      step({
        name: "Clone repository",
        uses: "actions/checkout@v6",
      }),
      installEndeStep,
      step({
        name: "Create Gist URL",
        env: {
          GITHUB_TOKEN: "${{ secrets.ENDE_RELEASE_PAT }}",
          GH_WORKFLOW_ACTOR: "${{ github.actor }}",
        },
        run:
          "ende run -A --quiet --lock=tools/deno.lock.json ./tools/release/00_start_release.ts",
      }),
    ],
  }],
});

const header = "# GENERATED BY ./start_release.ts -- DO NOT DIRECTLY EDIT";

export function generate() {
  return workflow.toYamlString({ header });
}

export const START_RELEASE_YML_URL = new URL(
  "./start_release.generated.yml",
  import.meta.url,
);

if (import.meta.main) {
  workflow.writeOrLint({ filePath: START_RELEASE_YML_URL, header });
}
